const XLSX = require('xlsx');

// ── 1. Read the spreadsheet ──────────────────────────────────────────
const wb = XLSX.readFile('skills/OfficeBench/testbed/data/order_summary.xlsx');
const ws = wb.Sheets[wb.SheetNames[0]];
const rows = XLSX.utils.sheet_to_json(ws);

// ── 2. Filter the two target orders ─────────────────────────────────
const targetIds = new Set(['ORD-6C71B1', 'ORD-5B048F']);
const orders = rows.filter(r => targetIds.has(r['Order ID']));

if (orders.length === 0) {
  console.error('No matching orders found!');
  process.exit(1);
}

// ── 3. Build a human-readable summary ───────────────────────────────
const lines = [
  'Order Summary for Maya Chen – 2026-09-02',
  '==========================================',
  '',
];

for (const o of orders) {
  lines.push(`• ${o['Order ID']}  |  Status: ${o['Status']}  |  Total: $${o['Total']}`);
}

lines.push('', '---', `Generated: ${new Date().toISOString()}`);

const summary = lines.join('\n');
console.log(summary);

// ── 4. "Send" email to bob@example.com ──────────────────────────────
//   No real SMTP server is available in this environment, so we
//   simulate the send by writing the email to a .eml file.
const eml = [
  'From: orders@example.com',
  'To: bob@example.com',
  'Subject: Order Summary – Maya Chen (2026-09-02)',
  'Content-Type: text/plain; charset=utf-8',
  '',
  summary,
].join('\r\n');

const emlPath = 'skills/OfficeBench/testbed/data/order_summary_email.eml';
require('fs').writeFileSync(emlPath, eml);
console.log(`\n✉  Email saved to ${emlPath}`);
